                                       const val = parseFloat(customChargeValue);
                                       if (isNaN(val) || val <= 0) return toast.warning("Enter a valid charge value");

                                       const newChg = {
                                          id: `custom-${Date.now()}`,
                                          name: customChargeName.trim(),
                                          type: customChargeType,
                                          value: val,
                                          isCustom: true
                                       };
                                       setAppliedAdditionalCharges(prev => [...prev, newChg]);
                                       setCustomChargeName('');
                                       setCustomChargeValue('');
                                    }}
                                    className="px-4 bg-[#18ba60] hover:bg-[#159a4f] text-white rounded-xl text-xs font-black uppercase transition-colors"
